import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs['DIM_CUSTOMER'].copy()
    stg = inputs['STG_CUSTOMER'].copy()

    # Preserve original dtypes info for is_current / customer_id if possible
    orig_is_current_dtype = dim['is_current'].dtype if 'is_current' in dim.columns else None
    orig_customer_id_dtype = dim['customer_id'].dtype if 'customer_id' in dim.columns else None

    if stg.empty:
        return {'dim_customer_out': dim}

    # Step 1: Deduplicate STG_CUSTOMER to latest record per customer_id by update_date.
    # On ties, keep the record with the greater (name, segment) pair (DESC lexicographic).
    stg_sorted = stg.sort_values(
        by=['customer_id', 'update_date', 'name', 'segment'],
        ascending=[True, False, False, False],
        kind='mergesort'  # stable sort to make tie-breaking deterministic
    )
    stg_dedup = stg_sorted.drop_duplicates(subset=['customer_id'], keep='first')

    dim = dim.reset_index(drop=True)

    def changed(a, b):
        a_null = pd.isna(a)
        b_null = pd.isna(b)
        if a_null and b_null:
            return False
        if a_null != b_null:
            return True
        return a != b

    new_rows = []

    for _, s in stg_dedup.iterrows():
        cid = s['customer_id']
        mask_current = (dim['customer_id'] == cid) & (dim['is_current'] == 1)
        current_idx = dim.index[mask_current]

        if len(current_idx) == 0:
            # No current row exists -> insert new version
            new_rows.append({
                'customer_id': cid,
                'name': s['name'],
                'segment': s['segment'],
                'eff_start_date': s['update_date'],
                'eff_end_date': pd.NaT,
                'is_current': 1
            })
        else:
            idx = current_idx[0]
            c_name = dim.at[idx, 'name']
            c_segment = dim.at[idx, 'segment']
            s_name = s['name']
            s_segment = s['segment']

            if changed(c_name, s_name) or changed(c_segment, s_segment):
                # Tracked-attribute change: expire current row, insert new version
                dim.at[idx, 'eff_end_date'] = s['update_date']
                dim.at[idx, 'is_current'] = 0
                new_rows.append({
                    'customer_id': cid,
                    'name': s_name,
                    'segment': s_segment,
                    'eff_start_date': s['update_date'],
                    'eff_end_date': pd.NaT,
                    'is_current': 1
                })
            # else: no change -> do nothing

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=[
            'customer_id', 'name', 'segment', 'eff_start_date', 'eff_end_date', 'is_current'
        ])
        dim = pd.concat([dim, new_df], ignore_index=True)

    # Restore dtypes where sensible
    if orig_customer_id_dtype is not None:
        try:
            dim['customer_id'] = dim['customer_id'].astype(orig_customer_id_dtype)
        except (ValueError, TypeError):
            pass

    if orig_is_current_dtype is not None:
        try:
            dim['is_current'] = dim['is_current'].astype(orig_is_current_dtype)
        except (ValueError, TypeError):
            pass

    return {'dim_customer_out': dim}
